# storyboard v6: physical products around the screen + vector animated product vignettes.
NAVY='#0A2A5E';BLUE='#1D2FC4';LB='#BFD2FF';GOLD='#FFD66B';CREAM='#FFF4D6';SK='#F2B78A';SK2='#C98A5B';COR='#FF7A6B';WH='#fff';GRN='#3DBE8B'
def svg(inner,bg,arrow=None,label=None,dark=True):
    ar=''
    if arrow=='up':ar=f'<path d="M280 10 L300 34 L260 34Z" fill="{GOLD}"><animate attributeName="opacity" values="1;.3;1" dur="1s" repeatCount="indefinite"/></path><rect x="140" y="0" width="280" height="5" fill="{GOLD}" opacity=".7"/>'
    if arrow=='down':ar=f'<path d="M280 305 L300 281 L260 281Z" fill="{GOLD}"/><rect x="140" y="310" width="280" height="5" fill="{GOLD}" opacity=".7"/>'
    if arrow=='right':ar=f'<path d="M550 157 L526 177 L526 137Z" fill="{GOLD}"/><rect x="555" y="80" width="5" height="155" fill="{GOLD}" opacity=".7"/>'
    lab=''
    if label:
        pos={'up':'x="280" y="54"','down':'x="280" y="272"','right':'x="470" y="162"'}[arrow]
        lab=f'<text {pos} text-anchor="middle" font-family="P" font-weight="700" font-size="14" fill="{GOLD}">{label}</text>'
    return f'<div class="sv"><svg viewBox="0 0 560 315" width="560" height="315"><rect width="560" height="315" fill="{bg}"/>{inner}{ar}{lab}</svg></div>'
def mug(x,y,s=1,photo=True,col=WH):
    return f'<g transform="translate({x} {y}) scale({s})"><rect x="0" y="0" width="60" height="70" rx="8" fill="{col}" stroke="{NAVY}" stroke-width="4"/><path d="M60 15 q28 0 28 22 q0 22 -28 22" fill="none" stroke="{NAVY}" stroke-width="6"/>'+(f'<rect x="12" y="14" width="36" height="34" rx="4" fill="{BLUE}"/><circle cx="30" cy="27" r="6" fill="{SK}"/><path d="M17 46 q13 -14 26 0Z" fill="{GOLD}"/>' if photo else '')+'</g>'
def steam(x,y):return f'<path d="M{x} {y} q-8 -14 0 -26 q8 -12 0 -24" fill="none" stroke="{LB}" stroke-width="4" stroke-linecap="round" stroke-dasharray="6 5"><animate attributeName="stroke-dashoffset" from="0" to="-22" dur="1.4s" repeatCount="indefinite"/></path>'
def person(x,y,tee=BLUE,hair=NAVY,s=1,skin=SK):
    return f'<g transform="translate({x} {y}) scale({s})"><circle cx="0" cy="-60" r="22" fill="{skin}"/><path d="M-22 -66 q22 -34 44 0 q-22 -10 -44 0Z" fill="{hair}"/><rect x="-26" y="-34" width="52" height="64" rx="14" fill="{tee}"/></g>'
