ORDER=[('TOP','↑ look up',['mug','magic','bottle','calendar'],'Mugs · magic mugs · bottles · calendars on a lit shelf above the screen'),('RIGHT','→ look right',['tee','lanyard','key'],'T-shirts on a rail, lanyards and keychains on pegs, right of the screen'),('BOTTOM','↓ look down',['printer','frame','polaroid','pad'],'3D prints, frames, polaroids and mouse pads on the counter below')]
TXT={'mug':('FOR YOUR COFFEE DATES','चाय-कॉफ़ी की मुलाक़ातों के लिए','चहा-कॉफीच्या भेटींसाठी'),'magic':('WATCH IT REVEAL','जादू देखिए','जादू पाहा'),'bottle':('YOUR NAME. YOUR BOTTLE.','आपका नाम, आपकी बोतल','तुमचं नाव, तुमची बाटली'),'calendar':('EVERY MONTH, YOUR MEMORIES','हर महीना, आपकी यादें','प्रत्येक महिना, तुमच्या आठवणी'),'tee':('WEAR YOUR STORY','अपनी कहानी पहनिए','तुमची गोष्ट परिधान करा'),'lanyard':('ID, IN YOUR STYLE','आपके स्टाइल में आईडी','तुमच्या स्टाइलमध्ये आयडी'),'key':('CARRY YOUR NAME','अपना नाम साथ रखिए','तुमचं नाव सोबत ठेवा'),'printer':('PRINTED LAYER BY LAYER','परत-दर-परत प्रिंट','थर-थर प्रिंट'),'frame':('MEMORIES ON THE WALL','दीवार पर यादें','भिंतीवर आठवणी'),'polaroid':('INSTANT MEMORIES','पलों की यादें','क्षणांच्या आठवणी'),'pad':('YOUR DESK, YOUR DESIGN','आपका डेस्क, आपका डिज़ाइन','तुमचा डेस्क, तुमचं डिझाइन')}
def card(k):
    n,ar,fr,desc,beats=G[k];t=TXT[k]
    rows=''.join(f'<tr><th>{a}</th><td>{b}</td></tr>' for a,b in beats)
    return f'<div class="card"><div class="cap" style="font-size:12px">{n} · edge arrow: {ar}</div>{fr}<div class="d">{desc}</div><table class="b">{rows}</table><div class="l3" style="margin-top:3px"><div><span class="chip">EN</span> {t[0]}</div><div><span class="chip">हिन्दी</span> {t[1]}</div><div><span class="chip">मराठी</span> {t[2]}</div></div></div>'
def page(t,sub,body):return f'<div class="pg"><div class="top"><h2>{t}</h2><small>{sub}</small></div>{body}</div>'
def tbl(h,rows):return '<table class="wide"><tr>'+''.join(f'<th>{x}</th>' for x in h)+'</tr>'+''.join('<tr>'+''.join(f'<td>{c}</td>' for c in r)+'</tr>' for r in rows)+'</table>'
def hookframe(txt,arrow=None,bg=NAVY,extra=''):
    return svg(extra+f'<text x="280" y="165" text-anchor="middle" font-family="P" font-weight="700" font-size="34" fill="#fff" style="filter:drop-shadow(0 0 8px #7FA6FF)">{txt}</text>',bg,arrow)
P=[]
P.append('''<div class="pg cover"><div style="margin-top:26mm"><div class="chip">STORYBOARD v6 · REAL PRODUCTS AROUND THE SCREEN · ALL-VECTOR ANIMATION</div><h1>The screen shows the idea.<br>The shelves show the real thing.</h1>
<div style="font-size:15px;color:#BFD2FF;margin-top:8px">A screen-and-shelf design: animated vector product stories on screen, real products above, below and right of it</div>
<ul style="margin-top:16px;font-size:12.5px;line-height:1.7;max-width:240mm"><li><b>No product photos or renders on screen.</b> Every product is a flat vector animation with a tiny story: a couple sipping coffee from photo mugs, a 3D printer building a figure, a gym-goer with a named bottle.</li>
<li><b>Edge arrows</b> bounce toward the real product: ↑ top, → right, ↓ bottom. The screen edge nearest the product glows in gold.</li>
<li><b>Stronger hook:</b> "Look up. Look down. Look right. It's all real. Come inside, touch it, feel it."</li>
<li>Rate-free · silent · 1920×1080 · English → हिन्दी → मराठी · about 2 min per language.</li></ul></div></div>''')
P.append(page('Shelf layout: where each of the 11 products sits','the physical shop front',
 '<div class="cols"><div><div class="lay"><div class="zt">TOP SHELF (look up) ↑<br><span>photo mugs · magic mugs · bottles · calendars</span></div><div class="mid"><div class="scr">SCREEN<br>vector stories</div><div class="zr">RIGHT RAIL →<br><span>T-shirts · lanyards · keychains</span></div></div><div class="zb">BOTTOM COUNTER (look down) ↓<br><span>3D prints · photo frames · polaroids · mouse pads</span></div></div></div><div>'+tbl(['#','Product','Zone','On-screen vector story'],[[i+1,G[k][0],ORDER_Z,G[k][3]] for i,(k,ORDER_Z) in enumerate([(k,z[0]) for z in ORDER for k in z[2]])])+'<div class="warn"><b>Tips:</b> light each zone separately; put a small card with the devdha.in QR on every shelf; keep items at eye level or just above; rotate stock weekly; bookmarks can replace any product that\'s out. The zones are a proposal: tell me if your shop layout differs and I\'ll move the arrows.</div></div></div>'))
P.append(page('The hook: three options and the one I recommend','all in 3 languages, word-by-word glow text',
 tbl(['Option','English','हिन्दी','मराठी'],[['A · Look around (recommended)','Look up. Look down. Look right. It\'s all real. Come inside. Touch it. Feel it.','ऊपर देखिए। नीचे देखिए। दाएँ देखिए। सब असली है। अंदर आइए। छूकर देखिए।','वर पाहा. खाली पाहा. उजवीकडे पाहा. सगळं खरं आहे. आत या. हातात घेऊन बघा.'],['B · Pictures can\'t','Pictures can\'t show how it feels. Come touch it.','तस्वीर में वो एहसास कहाँ? आइए, छूकर देखिए।','फोटोत ती अनुभूती कुठे? या, हातात घेऊन बघा.'],['C · Seen it on screen?','Looks good on screen? Wait till you hold it.','स्क्रीन पर अच्छा लगा? हाथ में लेकर देखिए।','स्क्रीनवर छान वाटलं? हातात घेऊन बघा.']])+
 '<div class="frs2">'+hookframe('is this just a screen?')+hookframe('look up','up',NAVY,'<rect x="150" y="14" width="260" height="8" rx="4" fill="#FFD66B"><animate attributeName="opacity" values="1;.2;1" dur=".8s" repeatCount="indefinite"/></rect>')+hookframe('look right','right')+hookframe('look down','down')+hookframe('it\'s all real.<tspan x="280" dy="40" font-size="26" fill="#FFE08A">come inside. touch it.</tspan>',None)+'</div><div class="lang">Choreography (0–9 s): "is this just a screen?" → arrow + glow ↑ with "look up" → → with "look right" → ↓ with "look down" → "it\'s all real." → "come inside. touch it. feel it." Each arrow bounces at the screen edge nearest the real shelf. Option B closes the product section; option C plays as the final line before Visit us.</div>'))
